css:
.app.p01-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "content"; }
.p01-col { max-width: 38rem; margin-inline: auto; display: grid; gap: var(--s-4); padding-block: var(--s-4); }
.p01-brand { display: flex; align-items: center; gap: var(--s-2); }
.p01-brand .brand__mark { width: 2rem; height: 2rem; }
.p01-questions { display: grid; gap: var(--s-2); }
.p01-signin { display: grid; gap: var(--s-2); justify-items: start; }
.p01-signin .banner { width: 100%; flex-wrap: wrap; }
.p01-signin .banner__text { flex: 1 1 12rem; }
.p01-google { min-width: min(100%, 17.5rem); gap: var(--s-3); }
.p01-g { font-weight: var(--fw-bold); font-size: var(--fs-body); }
.p01-google .spinner, .p01-wide .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p01-retry, .p01-wide { min-width: min(100%, 17.5rem); }
.p01-long { display: grid; gap: var(--s-4); }
.p01-e { --frame-w: var(--w2); }
.content.p01-stage { min-height: 100%; display: grid; place-items: center; }
.dialog.p01-ask { max-height: none; }
.p01-ask .dialog__foot { padding-bottom: var(--s-2); }
.p01-ask .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p01-notice { padding: var(--s-2) var(--s-4) 0; }
.p01-fine { margin: 0; padding: 0 var(--s-4) var(--s-4); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); max-width: var(--measure); }
.p01-fine strong { color: var(--ink); }
